'use client';
import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useAuth } from '@/context/AuthContext';
import { User, Activity, Search, ChevronDown, Calendar, LogOut, ShoppingCart } from 'lucide-react';
import LoginModal from './LoginModal';

export default function Navbar() {
  const { user, logout } = useAuth();
  const [showLogin, setShowLogin] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [location, setLocation] = useState('Mumbai, India');

  // Detect Location on Mount
  useEffect(() => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(async (position) => {
              const { latitude, longitude } = position.coords;
              try {
                  // Reverse Geocoding using OpenStreetMap (Proprietary free API)
                  const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                  const data = await res.json();
                  const city = data.address.city || data.address.town || data.address.state_district;
                  const area = data.address.suburb || data.address.neighbourhood || data.address.road;
                  if (city) setLocation(`${area ? area + ', ' : ''}${city}`);
              } catch (error) {
                  console.error("Location fetch failed", error);
              }
          }, (err) => {
              console.warn("Location permission denied", err);
          });
      }
  }, []);

  return (
    <>
      <nav style={{ 
        position: 'fixed', 
        top: 0, 
        left: 0, 
        right: 0, 
        zIndex: 1000, 
        height: 'var(--header-height)',
        background: '#fff',
        borderBottom: '1px solid #e5e7eb',
        display: 'flex',
        alignItems: 'center'
      }}>
        <div className="container" style={{ 
          width: '100%',
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          gap: '2rem'
        }}>
          {/* Logo & Location */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
              <Link href="/" style={{ 
                fontSize: '1.8rem', 
                fontWeight: '800', 
                display: 'flex', 
                alignItems: 'center', 
                gap: '8px',
                color: 'var(--brand)',
                textDecoration: 'none'
              }}>
                 <span style={{ color: 'var(--brand-yellow)' }}>Su</span>vidha
              </Link>
              
              {/* Location Display */}
              <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                   <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <span style={{ fontWeight: 'bold', fontSize: '0.95rem', color: '#1f2937', maxWidth: '250px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                            {location || 'Detecting Location...'}
                        </span>
                        <ChevronDown size={16} color="#1f2937" />
                   </div>
              </div>
          </div>

          {/* Nav Links */}
          <div style={{ display: 'flex', gap: '2rem', alignItems: 'center' }}>
             <Link href="/" style={{ fontWeight: '500', color: '#1f2937' }}>Home</Link>
             <Link href="/hospitals" style={{ fontWeight: '500', color: '#1f2937' }}>Services</Link>
          </div>
          
          {/* Right Actions */}
          <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
              {user ? (
                <div style={{ position: 'relative' }}>
                   <button 
                      onClick={() => setShowDropdown(!showDropdown)}
                      style={{ background: 'transparent', border: 'none', cursor: 'pointer', fontSize: '1rem', fontWeight: '500' }}
                   >
                     Profile
                   </button>
                   {/* Dropdown would go here similar to before */}
                   {showDropdown && (
                     <div style={{ position: 'absolute', top: '150%', right: 0, background: '#fff', border: '1px solid #ddd', borderRadius: '8px', padding: '10px', width: '180px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', display: 'flex', flexDirection: 'column', gap: '8px' }}>
                         <Link href="/bookings" style={{ textDecoration: 'none', color: '#374151', fontSize: '0.9rem', display: 'flex', alignItems: 'center', gap: '8px', padding: '5px' }}>
                            <Calendar size={16} /> Booking History
                         </Link>
                         <button onClick={logout} style={{ background: 'transparent', border: 'none', color: 'red', cursor: 'pointer', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '0.9rem', padding: '5px' }}>
                            <LogOut size={16} /> Logout
                         </button>
                     </div>
                   )}
                </div>
              ) : (
                <button 
                  onClick={() => setShowLogin(true)}
                  style={{ background: 'transparent', border: 'none', fontWeight: '500', fontSize: '1.1rem', cursor: 'pointer' }}
               >
                  Login
                </button>
              )}
              
              <button className="btn btn-primary" style={{ borderRadius: '8px', display: 'flex', alignItems: 'center', gap: '8px', padding: '0.6rem 1.2rem' }}>
                  <ShoppingCart size={18} /> My Cart
              </button>
          </div>
        </div>
      </nav>
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} />
    </>
  );
}
